using OcctSharp.DocumentProjections;
using OcctSharp.StepCafWorkspaces;
using OcctSharp.XdeMetadataWorkspaces;
namespace OcctSharp.Runtime.Tests;
public sealed class XdeMetadataWorkspaceTests {
 [Fact]public void FullMetadataHistoryPersistenceAssemblyAndConsumerWorkflow()=>OcctSharp.Tests.Shared.BatchAXMetadataWorkflow.Run();
 [Fact]public void EmptySnapshotDoesNotInitializeToolsAndSurvivesOwnerDisposal(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);var a=metadata.Snapshot();Assert.Empty(a.Colors);Assert.Empty(a.Views);Assert.Empty(a.Materials);Assert.Empty(a.Dimensions);doc.Dispose();Assert.Empty(a.Views);Assert.Throws<ObjectDisposedException>(()=>metadata.Snapshot());}
 [Fact]public void ForeignContextLabelsAndDuplicatesAreRejected(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var a=DocumentProjectionContext.Bind(doc);using var b=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(a);var label=b.GetLabel("0:1");Assert.Throws<ArgumentException>(()=>metadata.SetColors([new(label,MetadataColorChannel.General,new(1,0,0))]));var own=a.GetLabel("0:1");Assert.Throws<ArgumentException>(()=>metadata.Snapshot([own,own]));}
 [Fact]public void MutationsNeedCommandAndInitializedShapeDomain(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);Assert.ThrowsAny<Exception>(()=>metadata.CreateMaterial("material",new(1,0,0),.5,.5,[]));doc.NewCommand();var main=context.GetLabel("0:1");Assert.ThrowsAny<Exception>(()=>metadata.SetColors([new(main,MetadataColorChannel.General,new(1,0,0))]));Assert.Empty(metadata.Snapshot().Colors);doc.AbortCommand();}
 [Fact]public void InvalidLaterBatchTargetCannotPartiallyChangeEarlierColor(){using var document=XdeDocument.Create();using var box=ShapeFactory.CreateBox(1,1,1);using var transaction=document.BeginTransaction();var shape=document.AddShape(box,"shape");using var metadata=XdeMetadataContext.Bind(document.Projections);var label=document.Projections.GetLabel(shape.Entry);metadata.SetColors([new(label,MetadataColorChannel.General,new(.25,.5,.75))]);var main=document.Projections.GetLabel("0:1");Assert.ThrowsAny<Exception>(()=>metadata.SetColors([new(label,MetadataColorChannel.General,new(1,0,0)),new(main,MetadataColorChannel.General,new(1,0,0))]));Assert.Equal(.25,metadata.Snapshot([label]).Targets.Single().General!.Red,6);}
 [Fact]public void BoundContextDisposalRejectsAccessWhileDetachedSnapshotsRemainReadable(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);var detached=metadata.Snapshot();context.Dispose();Assert.Throws<ObjectDisposedException>(()=>metadata.Snapshot());Assert.Empty(detached.Targets);}
 [Fact]public void InvalidValuesModesAndTextAreRejectedBeforeNativeMutation(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);Assert.ThrowsAny<ArgumentException>(()=>metadata.CreateMaterial("x",new(double.NaN,0,0),0,0,[]));Assert.ThrowsAny<ArgumentException>(()=>metadata.CreateDimension(20,"x","x",[double.NaN],[]));Assert.ThrowsAny<ArgumentException>(()=>metadata.CreateView("x\0",[]));Assert.Throws<ArgumentOutOfRangeException>(()=>StepCafFiles.Read("x",(StepCafReadModes)2048));Assert.Throws<ArgumentOutOfRangeException>(()=>StepCafFiles.Write(context,"x",(StepCafWriteModes)2048));}
 static StepCafReadResult Imported(){string path=Path.Combine(Path.GetTempPath(),"OcctSharp.AX.Lifetime."+Guid.NewGuid()+".step");try{using var box=ShapeFactory.CreateBox(1,1,1);ShapeExchange.WriteStep(box,path);return StepCafFiles.Read(path);}finally{File.Delete(path);}}
 [Fact]public void UnprovedBareDocumentCannotCreateNamingBackedCamera(){using var doc=DocumentProjectionContext.CreateNativeDocument();using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);doc.NewCommand();Assert.ThrowsAny<Exception>(()=>metadata.CreateView("view",[]));Assert.Empty(metadata.Snapshot().Views);doc.AbortCommand();}
 [Fact]public void ViewLockRemoveAbortAndSnapshotLifetime(){
  using var imported=Imported();var doc=imported.Document;using var context=DocumentProjectionContext.Bind(doc);using var metadata=XdeMetadataContext.Bind(context);
  void Views(int count,string stage)=>Assert.True(metadata.Snapshot().Views.Count==count,stage+"; command="+doc.HasOpenCommand()+"; undos="+doc.GetAvailableUndos());
  doc.NewCommand();var shape=context.GetLabel(imported.Diagnostics.FreeRoots.Single().Entry);var dim=metadata.CreateDimension(20,"size","size",[1.5],[shape]);var view=metadata.CreateView("view",[shape],[dim]);Views(1,"after create");metadata.SetViewLocked(view,true);Assert.True(metadata.Snapshot().Views.Single().Locked);metadata.SetViewLocked(view,false);Assert.False(metadata.Snapshot().Views.Single().Locked);Assert.True(doc.CommitCommand());Views(1,"after commit");var detached=metadata.Snapshot();doc.NewCommand();metadata.RemoveView(view);Views(0,"after remove");doc.AbortCommand();Views(1,"after abort");var restored=metadata.Snapshot().Views.Single();Assert.Equal(shape.Entry,restored.ShapeEntries.Single());Assert.Equal(dim.Entry,restored.DimensionEntries.Single());doc.NewCommand();metadata.RemoveView(view);Assert.True(doc.CommitCommand());Views(0,"after committed remove");Assert.True(doc.Undo());Views(1,"after removal undo");Assert.Equal(shape.Entry,metadata.Snapshot().Views.Single().ShapeEntries.Single());Assert.True(doc.Redo());Views(0,"after removal redo");metadata.Dispose();Assert.Single(detached.Views);Assert.Throws<ObjectDisposedException>(()=>metadata.Snapshot());
 }
 [Theory][InlineData(DocumentStorageFormat.BinXcaf)][InlineData(DocumentStorageFormat.XmlXcaf)]
 public void ExactColorPersistenceRetainsAlphaAndTransparentBlack(DocumentStorageFormat format){
  string file=Path.Combine(Path.GetTempPath(),"OcctSharp.AX.Color."+Guid.NewGuid()+(format==DocumentStorageFormat.BinXcaf?".xbf":".xml"));try{using var document=XdeDocument.Create();using var box=ShapeFactory.CreateBox(1,1,1);string entry;using(var transaction=document.BeginTransaction()){var shape=document.AddShape(box,"color");entry=shape.Entry;using var metadata=XdeMetadataContext.Bind(document.Projections);var label=document.Projections.GetLabel(entry);metadata.SetColors([new(label,MetadataColorChannel.General,new(0,0,0,0))]);metadata.SetColors([new(label,MetadataColorChannel.Surface,new(.123456,.654321,.333333,.25))]);Assert.True(transaction.Commit());}document.Save(file,format);using var opened=XdeDocument.Open(file);using var read=XdeMetadataContext.Bind(opened.Projections);var target=read.Snapshot([opened.Projections.GetLabel(entry)]).Targets.Single();Assert.Equal(0,target.General!.Red);Assert.Equal(0,target.General.Alpha);Assert.Equal(.123456,target.Surface!.Red,6);Assert.Equal(.654321,target.Surface.Green,6);Assert.Equal(.333333,target.Surface.Blue,6);Assert.Equal(.25,target.Surface.Alpha,6);}finally{File.Delete(file);}
 }
 [Theory][InlineData(false)][InlineData(true)]
 public void XmlColorLegacyFallbackAndMalformedExtension(bool malformed){
  string file=Path.Combine(Path.GetTempPath(),"OcctSharp.AX.Legacy."+Guid.NewGuid()+".xml");try{using var document=XdeDocument.Create();using var box=ShapeFactory.CreateBox(1,1,1);string entry;using(var transaction=document.BeginTransaction()){var shape=document.AddShape(box,"red");entry=shape.Entry;using var metadata=XdeMetadataContext.Bind(document.Projections);metadata.SetColors([new(document.Projections.GetLabel(entry),MetadataColorChannel.General,new(1,0,0))]);Assert.True(transaction.Commit());}document.Save(file,DocumentStorageFormat.XmlXcaf);string xml=File.ReadAllText(file);Assert.Contains("occtsharp_rgba_v1=",xml);xml=System.Text.RegularExpressions.Regex.Replace(xml,"occtsharp_rgba_v1=\"[^\"]*\"",malformed?"occtsharp_rgba_v1=\"RGBA1:BAD\"":"");File.WriteAllText(file,xml);if(malformed){Assert.ThrowsAny<Exception>(()=>{using var opened=XdeDocument.Open(file);});}else{using var opened=XdeDocument.Open(file);using var metadata=XdeMetadataContext.Bind(opened.Projections);Assert.Equal(1,metadata.Snapshot([opened.Projections.GetLabel(entry)]).Targets.Single().General!.Red,6);}}finally{File.Delete(file);}
 }

}
